/**
 * Disruptive mosaic pixelation reveal — the legacy-mode "shader" module.
 *
 * A cinematic, low-frame-rate settle: the app (3D models included) is fully
 * composed behind a black cover, then its pixelated image tears itself
 * together out of big displaced blocks. `duration` (default 2000ms) covers
 * the transition; the fade runs as its own tail after it:
 *
 *   1. BLACK — an opaque cover from the very first frame.
 *   2. POP-IN — huge square pixels appear in noise-random order, each one
 *      DISPLACED from its true position by a coherent random vector field
 *      (neighboring shards drift together). Colors come from a one-time
 *      SNAPSHOT of the actual page, so the blocks are the project itself.
 *   3. SETTLE + SHRINK — every tick (the whole animation is quantized to
 *      TICK_FPS for a stop-motion, filmic feel) the blocks shrink by a
 *      constant ratio and glide toward their proper place; displacement hits
 *      zero mid-flight, and the now-aligned mosaic keeps refining until the
 *      blocks are tiny — a close pixelated match of the app as `duration`
 *      elapses.
 *   4. FADE — for FADE_MS after `duration`, the finest mosaic dissolves
 *      (smoothly, full frame rate) over the real project.
 *
 * Efficiency: the DOM is rasterized ONCE into a small offscreen canvas
 * (element background rects, faint text strips, and real pixels drawn from
 * <img>/<video>/<canvas> elements — no libraries, no getImageData). Frames
 * between ticks return without painting; a displaced tick draws at most a
 * couple thousand tiles, and an aligned tick is a single nearest-neighbor
 * blit of a cached cols×rows canvas. No per-pixel JS in the hot loop.
 *
 * Framework-agnostic: hand it the compositor root; it drives the <canvas>
 * inside and leaves the other grade layers inert.
 */
export interface MosaicRevealOptions {
  /**
   * Length of the pixelation transition in ms (black → pop-in → settle to
   * tiny aligned blocks). The fade-out runs for FADE_MS *after* this, so
   * total runtime is duration + FADE_MS.
   */
  duration?: number;
  /** 0–1: how far blocks start displaced from their proper position. */
  disruption?: number;
  /** Unused since the snapshot rework; kept so existing call sites/schema work. */
  blur?: number;
  /** Called once when the reveal finishes or is skipped. */
  onDone?: () => void;
}

type RGB = [number, number, number];

const MIN_CELL = 1; // requested floor; clamped to snapshot resolution at run time
const SNAP_MAX_W = 512; // snapshot resolution cap
const TICK_FPS = 12; // the transition only updates this often — cinematic low fps
const BLACK_END = 0.1; // transition fractions: black hold…
const FORM_END = 0.3; // …then displaced pop-in…
const SETTLE_END = 0.6; // …displacement reaches zero here; pure shrink follows
const FADE_MS = 600; // fade tail AFTER the transition, over the live app

const clamp = (value: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, value));
const smoothstep = (t: number) => t * t * (3 - 2 * t);

// Deterministic hash in [0,1) — one stream of per-run randomness via `seed`.
function hash01(n: number, seed: number): number {
  const x = Math.sin(n * 127.1 + seed * 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function parseColor(input: string): RGB | null {
  const s = input.trim();
  if (s.startsWith('#')) {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
    if (hex.length < 6) return null;
    const n = parseInt(hex.slice(0, 6), 16);
    if (Number.isNaN(n)) return null;
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  const match = s.match(/rgba?\(([^)]+)\)/);
  if (match?.[1]) {
    const [r, g, b] = match[1].split(',').map((p) => parseFloat(p));
    if (r !== undefined && g !== undefined && b !== undefined && Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b)) {
      return [r, g, b];
    }
  }
  return null;
}

function readToken(name: string, fallback: RGB): RGB {
  return parseColor(getComputedStyle(document.documentElement).getPropertyValue(name)) ?? fallback;
}

/**
 * One-time rasterization of the live page into a small offscreen canvas.
 * Approximations are deliberate (documented) — at mosaic scale they read
 * correctly: element background rects in document order (≈ paint order),
 * translucent strips where text lives, and real pixels for media elements.
 * A WebGL canvas without preserveDrawingBuffer may blit blank — the panel
 * background underneath then stands in for it.
 */
function captureSnapshot(skipRoot: HTMLElement, ground: RGB): HTMLCanvasElement | null {
  const W = Math.max(1, window.innerWidth);
  const H = Math.max(1, window.innerHeight);
  const scale = Math.min(1, SNAP_MAX_W / W);
  const snap = document.createElement('canvas');
  snap.width = Math.max(1, Math.round(W * scale));
  snap.height = Math.max(1, Math.round(H * scale));
  const ctx = snap.getContext('2d');
  if (!ctx) return null;

  ctx.fillStyle = `rgb(${ground[0]}, ${ground[1]}, ${ground[2]})`;
  ctx.fillRect(0, 0, snap.width, snap.height);

  const all = document.body.getElementsByTagName('*');
  const limit = Math.min(all.length, 4000); // hard cap keeps the pass bounded
  for (let i = 0; i < limit; i++) {
    const el = all[i];
    if (!el || skipRoot.contains(el)) continue;
    const tag = el.tagName;
    if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'LINK') continue;
    const r = el.getBoundingClientRect();
    if (r.width < 2 || r.height < 2 || r.bottom < 0 || r.right < 0 || r.top > H || r.left > W) continue;
    const cs = getComputedStyle(el);
    if (cs.visibility !== 'visible') continue;
    const opacity = parseFloat(cs.opacity);
    if (opacity < 0.05) continue;
    const x = r.left * scale;
    const y = r.top * scale;
    const w = r.width * scale;
    const h = r.height * scale;

    // Real pixels for media — this is what makes the 3D/photo areas resemble
    // themselves in the mosaic rather than flat placeholders.
    if (el instanceof HTMLImageElement || el instanceof HTMLVideoElement || el instanceof HTMLCanvasElement) {
      try {
        ctx.globalAlpha = opacity;
        ctx.drawImage(el, x, y, w, h);
        ctx.globalAlpha = 1;
      } catch {
        // Zero-size / not-ready media: the background underneath stands in.
      }
      continue;
    }

    const bg = cs.backgroundColor;
    if (bg && bg !== 'transparent' && !bg.startsWith('rgba(0, 0, 0, 0')) {
      ctx.globalAlpha = opacity;
      ctx.fillStyle = bg;
      ctx.fillRect(x, y, w, h);
      ctx.globalAlpha = 1;
    }
    // Faint ink strip where a text run lives, so type-dense panels read as
    // texture instead of blank fills. Only leaf-ish rows, kept very cheap.
    const first = el.firstChild;
    if (h * (1 / scale) < 60 && first?.nodeType === Node.TEXT_NODE && first.textContent && first.textContent.trim()) {
      ctx.globalAlpha = 0.3 * opacity;
      ctx.fillStyle = cs.color;
      ctx.fillRect(x, y + h * 0.32, w, h * 0.36);
      ctx.globalAlpha = 1;
    }
  }
  return snap;
}

/** Clear any inline styles a previous engine version left on the grade layers. */
function resetGradeLayers(root: HTMLElement) {
  const backdrop = root.querySelector<HTMLElement>('[data-amp-backdrop]');
  if (backdrop) {
    backdrop.style.transition = '';
    backdrop.style.backdropFilter = '';
    backdrop.style.removeProperty('-webkit-backdrop-filter');
  }
  for (const selector of ['[data-amp-scanlines]', '[data-amp-vignette]']) {
    const el = root.querySelector<HTMLElement>(selector);
    if (el) {
      el.style.transition = '';
      el.style.opacity = '';
    }
  }
}

/**
 * Run the reveal against a compositor root containing a <canvas>. Returns a
 * cancel function that stops the animation and clears everything immediately.
 */
export function runMosaicReveal(root: HTMLElement, options: MosaicRevealOptions = {}): () => void {
  const { duration = 2000, disruption = 0.75, onDone } = options;

  const canvas = root.querySelector('canvas');
  const ctx = canvas?.getContext('2d') ?? null;
  resetGradeLayers(root);

  const bail = () => {
    if (canvas && ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
    onDone?.();
    return () => {};
  };
  if (!canvas || !ctx) return bail();
  // Honor reduced-motion: no disruptive animation at all.
  if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return bail();

  const W = Math.max(1, window.innerWidth);
  const H = Math.max(1, window.innerHeight);
  canvas.width = W; // resizing resets ctx state — configure below, after this
  canvas.height = H;

  // 1. BLACK, synchronously — no flash of the app before the first RAF.
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, W, H);

  const ground = readToken('--amp-bg', [244, 244, 246]);
  const accent = readToken('--amp-accent', [109, 59, 255]);
  const seed = Math.random() * 1000; // fresh displacement field every run
  const snapshot = captureSnapshot(root, ground);

  // Blocks finer than the snapshot's own resolution add nothing and would
  // smear on upscale — clamp the floor so the finest mosaic stays crisp.
  const minCell = Math.max(MIN_CELL, Math.ceil(W / (snapshot?.width ?? SNAP_MAX_W)));
  const startCell = clamp(Math.round(Math.min(W, H) / 6), 48, 320);

  // Continuous shrink in log space: every tick reduces the block size by the
  // same RATIO, which is how "pixels getting finer" actually reads — linear
  // px/ms would crawl at the start and dump all the detail at the end.
  const lnStart = Math.log(startCell);
  const lnEnd = Math.log(minCell);
  const cellAt = (q: number) => Math.max(minCell, Math.round(Math.exp(lnStart + (lnEnd - lnStart) * q)));

  // Displacement: a coarse random vector field (shards of neighboring blocks
  // drift together) plus per-tile jitter, fully decayed by SETTLE_END. While
  // it is active, blocks are large (few thousand at most), so the per-tile
  // draw path stays cheap; once aligned, frames are a single blit.
  const maxDisp = Math.min(W, H) * 0.32 * disruption;
  const ampAt = (p: number) =>
    p >= SETTLE_END ? 0 : p <= FORM_END ? 1 : 1 - smoothstep((p - FORM_END) / (SETTLE_END - FORM_END));

  // Low-res mosaic cache, keyed by cell size: rebuilt at most once per tick
  // (a single GPU downscale of the snapshot).
  const low = document.createElement('canvas');
  const lowCtx = low.getContext('2d');
  if (!lowCtx) return bail();
  let lowCell = -1;
  const ensureLow = (cell: number) => {
    if (cell === lowCell) return;
    lowCell = cell;
    low.width = Math.ceil(W / cell) + 1;
    low.height = Math.ceil(H / cell) + 1;
    lowCtx.imageSmoothingEnabled = true; // box-average = true mosaic sampling
    if (snapshot) {
      lowCtx.drawImage(snapshot, 0, 0, low.width, low.height);
    } else {
      // Capture unavailable (headless/foreign engine): theme-tinted fallback.
      for (let cy = 0; cy < low.height; cy++) {
        for (let cx = 0; cx < low.width; cx++) {
          const n = hash01(cx * 31 + cy * 57, seed);
          lowCtx.fillStyle = n > 0.86
            ? `rgb(${accent[0]}, ${accent[1]}, ${accent[2]})`
            : `rgb(${ground[0] * (0.7 + 0.3 * n) | 0}, ${ground[1] * (0.7 + 0.3 * n) | 0}, ${ground[2] * (0.7 + 0.3 * n) | 0})`;
          lowCtx.fillRect(cx, cy, 1, 1);
        }
      }
    }
  };

  const start = performance.now();
  let raf = 0;
  let cancelled = false;
  let lastTick = -1;

  const frame = (now: number) => {
    if (cancelled) return;
    const elapsed = now - start;

    if (elapsed >= duration + FADE_MS) {
      ctx.clearRect(0, 0, W, H);
      onDone?.();
      return;
    }

    if (elapsed < duration) {
      // ---- TRANSITION, quantized to TICK_FPS for the stop-motion look ----
      const tick = Math.floor((elapsed * TICK_FPS) / 1000);
      if (tick === lastTick) {
        raf = requestAnimationFrame(frame); // hold the frame — low fps
        return;
      }
      lastTick = tick;

      const p = elapsed / duration;
      if (p >= BLACK_END) {
        const q = p < FORM_END ? 0 : (p - FORM_END) / (1 - FORM_END);
        const cell = cellAt(q);
        const amp = ampAt(p);
        const formT = clamp((p - BLACK_END) / (FORM_END - BLACK_END), 0, 1);
        ensureLow(cell);
        ctx.imageSmoothingEnabled = false; // crisp squares, never smoothed
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, W, H);

        if (amp > 0.01) {
          // Displaced pass: draw every visible tile at its drifted position.
          // 2/3. POP-IN and the displaced half of the settle.
          for (let cy = 0; cy < low.height; cy++) {
            for (let cx = 0; cx < low.width; cx++) {
              const appear = hash01(cx * 31 + cy * 57 + 7, seed) * 0.82;
              if (formT < appear) continue; // not popped in yet
              // Coarse field cell → shards drift together; jitter breaks edges.
              const qu = Math.floor(((cx + 0.5) * cell * 14) / W);
              const qv = Math.floor(((cy + 0.5) * cell * 9) / H);
              const fx = hash01(qu * 13.3 + qv * 7.7 + 31, seed) - 0.5;
              const fy = hash01(qu * 3.1 + qv * 17.9 + 57, seed) - 0.5;
              const jx = (hash01(cx * 31 + cy * 57 + 101, seed) - 0.5) * cell * 0.8;
              const jy = (hash01(cx * 57 + cy * 31 + 137, seed) - 0.5) * cell * 0.8;
              const dx = Math.round(cx * cell + (fx * 2 * maxDisp + jx) * amp);
              const dy = Math.round(cy * cell + (fy * 2 * maxDisp + jy) * amp);
              ctx.drawImage(low, cx, cy, 1, 1, dx, dy, cell, cell);
              const age = formT - appear;
              if (age >= 0 && age < 0.12) {
                // Brief accent flash as each block lands.
                ctx.fillStyle = `rgba(${accent[0]}, ${accent[1]}, ${accent[2]}, ${(0.55 * (1 - age / 0.12)).toFixed(3)})`;
                ctx.fillRect(dx, dy, cell, cell);
              }
            }
          }
        } else {
          // Aligned pass: displacement is gone; the mosaic keeps refining
          // tick by tick until the blocks are tiny. One blit.
          ctx.drawImage(low, 0, 0, low.width, low.height, 0, 0, low.width * cell, low.height * cell);
        }
      }
    } else {
      // 4. FADE — smooth (not tick-quantized): the finest aligned mosaic
      // dissolves over the real app for FADE_MS.
      ensureLow(minCell);
      const alpha = 1 - (elapsed - duration) / FADE_MS;
      ctx.imageSmoothingEnabled = false;
      ctx.clearRect(0, 0, W, H);
      ctx.globalAlpha = clamp(alpha, 0, 1);
      ctx.drawImage(low, 0, 0, low.width, low.height, 0, 0, low.width * minCell, low.height * minCell);
      ctx.globalAlpha = 1;
    }

    raf = requestAnimationFrame(frame);
  };
  raf = requestAnimationFrame(frame);

  return () => {
    cancelled = true;
    cancelAnimationFrame(raf);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };
}
